import numpy as np

def bootstrap_ci(scores: np.ndarray, n_boot: int = 500) -> tuple[float, float]:
    rng = np.random.default_rng(42)
    means = [float(np.mean(rng.choice(scores, size=len(scores), replace=True))) for _ in range(n_boot)]
    lo, hi = np.percentile(means, [2.5, 97.5])
    return (float(lo), float(hi))

import numpy as np

def compute_psi(expected: np.ndarray, actual: np.ndarray) -> float:
    e = np.clip(expected, 1e-6, 1.0)
    a = np.clip(actual, 1e-6, 1.0)
    return float(np.sum((a - e) * np.log(a / e)))

from sklearn.compose import ColumnTransformer
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder

def build_preprocessor(num_cols: list[str], cat_cols: list[str]) -> Pipeline:
    prep = ColumnTransformer(
        transformers=[
            ("num", SimpleImputer(strategy="median"), num_cols),
            ("cat", OneHotEncoder(handle_unknown="ignore"), cat_cols),
        ]
    )
    return Pipeline(steps=[("prep", prep)])

