def verify_rag_citations(answer_citations: list[str], chunks: list[dict], min_score: float = 0.65) -> bool:
    valid_ids = {c["id"] for c in chunks if c.get("score", 0.0) >= min_score}
    if not valid_ids or not answer_citations:
        return False
    return set(answer_citations).issubset(valid_ids)

